    'IVX_ANTHROPIC_API_KEY',
    'IVX_AI_GATEWAY_KEY',
    'AI_GATEWAY_API_KEY',
    'OPENAI_API_KEY',
  ];
  const presence: Record<string, { present: boolean; length: number; prefix: string }> = {};
  for (const name of vars) {
    const val = (process.env[name] ?? '').trim();
    presence[name] = {
      present: val.length > 0,
      length: val.length,
      prefix: val.length > 0 ? `${val.slice(0, 4)}***` : 'none',
    };
  }
  return Response.json({
